<?php
$u=sr_auth('recruiter');$jobs=sr_all('SELECT j.*,(SELECT COUNT(*) FROM applications a WHERE a.job_id=j.id) applicants FROM jobs j WHERE j.recruiter_id=? ORDER BY j.id DESC',[$u['id']]);
sr_page_heading('TRANG QUẢN LÝ','Tin tuyển dụng của tôi','Tạo, chỉnh sửa và theo dõi hồ sơ ứng tuyển của từng vị trí.');
?><div class="toolbar"><span><strong><?=count($jobs)?></strong> tin tuyển dụng</span><a class="button primary" href="<?=sr_url('job_form')?>">+ Đăng tin tuyển dụng</a></div>
<?php if(!$jobs):?><div class="panel empty-state"><h2>Hãy đăng tin tuyển dụng đầu tiên</h2><p>Mỗi tin sẽ được quản trị viên phê duyệt trước khi xuất hiện công khai.</p><a class="button primary" href="<?=sr_url('job_form')?>">Tạo tin mới</a></div><?php else:?><div class="panel table-panel"><div class="table-responsive"><table><thead><tr><th>Vị trí / Công ty</th><th>Ngày đăng</th><th>Ứng viên</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($jobs as $j):?><tr><td><strong><?=h($j['title'])?></strong><small><?=h($j['company'])?></small></td><td><?=h(sr_date($j['created_at']))?></td><td><a href="<?=sr_url('applicants',['job_id'=>$j['id']])?>"><?=h($j['applicants'])?> ứng viên</a></td><td><span class="badge <?=sr_state_class($j['status'])?>"><?=h(sr_status($j['status']))?></span></td><td><div class="table-actions"><a class="button secondary xs" href="<?=sr_url('job_form',['id'=>$j['id']])?>">Sửa</a><form method="post" data-confirm="Ẩn tin này khỏi danh sách công khai?"><?=sr_token()?><input type="hidden" name="action" value="job_close"><input type="hidden" name="id" value="<?=$j['id']?>"><button class="button ghost xs" type="submit">Ẩn tin</button></form><?php if((int)$j['applicants']===0):?><form method="post" data-confirm="Xóa vĩnh viễn tin tuyển dụng này?"><?=sr_token()?><input type="hidden" name="action" value="job_delete"><input type="hidden" name="id" value="<?=$j['id']?>"><button class="button danger-outline xs" type="submit">Xóa</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?><div class="privacy-note">Sau khi sửa nội dung, trạng thái tin sẽ trở về “Chờ duyệt”. Tin đã có ứng viên không thể xóa để bảo toàn lịch sử ứng tuyển.</div>
